-- Biblioteca Inclusiva · Geografia do 6º ano completa.
WITH lessons(code,title,goal) AS (VALUES
('EF06GE01','Paisagens e transformações','Comparar paisagens em tempos distintos e identificar mudanças, permanências e agentes transformadores.'),
('EF06GE02','Paisagens de diferentes sociedades','Analisar transformações territoriais realizadas por diferentes sociedades com respeito a conhecimentos e direitos.'),
('EF06GE03','Movimentos da Terra e dinâmica climática','Relacionar movimentos da Terra, circulação atmosférica e ritmos climáticos usando modelos e evidências.'),
('EF06GE04','Ciclo da água e bacias hidrográficas','Explicar ciclo da água, escoamento e bacias relacionando cobertura vegetal, solo e ações humanas.'),
('EF06GE05','Clima e circulação atmosférica','Distinguir tempo e clima e interpretar fatores e elementos climáticos em diferentes escalas.'),
('EF06GE06','Geodinâmica e tectônica de placas','Explicar processos internos da Terra e sua relação com relevo e distribuição de fenômenos geológicos.'),
('EF06GE07','Paisagens climatobotânicas','Relacionar clima, relevo, solo, água e vegetação em grandes conjuntos de paisagens mundiais.'),
('EF06GE08','Escalas e distâncias','Aplicar escala gráfica e numérica para comparar distâncias e níveis de detalhamento cartográfico.'),
('EF06GE09','Curvas de nível e perfil topográfico','Interpretar curvas de nível e perfis topográficos por altitude, declividade e forma do relevo.'),
('EF06GE10','Uso do solo e da água','Analisar transformações do solo e da água no campo e na cidade por atividades econômicas e infraestrutura.'),
('EF06GE11','Sociedade, natureza e biodiversidade','Explicar interações entre componentes naturais, biodiversidade e ações sociais em diferentes escalas.'),
('EF06GE12','Consumo de água','Comparar usos da água por setor, território e tecnologia sem reduzir a questão ao consumo individual.'),
('EF06GE13','Práticas humanas e consequências ambientais','Avaliar consequências ambientais de práticas humanas, grupos envolvidos e alternativas sustentáveis.')
), normalized AS (
 SELECT code,'src/escola-brilha/curso-v4/geografia-6ano/dados-fund2.ts'::text AS source_key,title,goal FROM lessons
)
